    unsigned restored=0;for(unsigned i=0;i<64;++i){CB_REQUIRE(call(CB_GRAPHICS_INFO,NULL,0)==CB_OK);struct cb_graphics_info current;cb_copy(&current,cb_result(&client),sizeof(current));if(current.surfaces==baseline.surfaces+1){restored=1;break;}}CB_REQUIRE(restored);CB_REQUIRE(call(CB_GRAPHICS_SURFACE_RELEASE,&surface,8)==CB_OK);CB_REQUIRE(call(CB_GRAPHICS_SURFACE_INFO,&surface,8)==CB_DENIED);CB_REQUIRE(cb_write_all(&client,cb_standard(2),"stderr ok\n",10)==CB_OK);CB_REQUIRE(cb_write_all(&client,cb_standard(1),"graphics ok\n",12)==CB_OK);cb_exit(0);
